package settings

// Templates copy configuration only at registration. They do not connect to
// external systems, establish official SLA or silently update existing tenants.
func additionalOrganization(kind string) (OrganizationTemplate, bool) {
	var t OrganizationTemplate
	switch kind {
	case "financial_university":
		t, _ = Organization("education")
		t.Type = kind
		t.ExampleTitles = []string{"Доступ к системе", "Служебная командировка", "Авансовый отчёт"}
		t.Name = "Финансовый университет при Правительстве Российской Федерации"
		t.Heading = "Поддержка сотрудников и обучающихся Финуниверситета"
		t.Demonstration = true
		t.Notice = "Демонстрационная конфигурация. Подтверждены названия трёх подразделений по официальным страницам. Маршруты, сроки, согласования и инструкции требуют проверки университетом; внешние интеграции не настроены."
		t.Sources = []TemplateSource{{"https://www.fa.ru/university/structure/university/dct/", "Название: Дирекция цифровых технологий", "2026-11-28"}, {"https://www.fa.ru/university/structure/university/ko/", "Название: Управление кадрового обеспечения", "2026-11-28"}, {"https://www.fa.ru/university/structure/university/buio/", "Название: Управление бухгалтерского учета и отчетности", "2026-11-28"}, {"https://www.fa.ru/upload/iblock/5b8/jjhz83f0358orfhvm4qgu1hmqeo1ag6h/Polozhenie-o-sluzhebnykh-komandirovkakh.pdf", "Официальный файл о командировках; действительность редакции и применимость требуют подтверждения; нормы не перенесены в автоответы", "2026-11-28"}}
		t.Examples = []string{"Не получается войти во внутреннюю информационную систему.", "Нужно согласовать служебную командировку.", "Нужно передать авансовый отчёт на проверку."}
		t.Builder.Departments = []Department{{"IT", "Дирекция цифровых технологий"}, {"HR", "Управление кадрового обеспечения"}, {"Accounting", "Управление бухгалтерского учета и отчетности"}, {"Facilities", "Демонстрационная очередь АХО; официальный маршрут требует проверки"}, {"Records", "Демонстрационная очередь документооборота"}, {"Approvals", "Демонстрационная очередь межподразделенческих согласований"}, {"Academic", "Демонстрационная очередь обращений обучающихся"}}
		t.Documents = []StarterDocument{
			{"employee_access", "IT", "Демо: доступ сотрудника к информационной системе", "доступ, информационная система, вход", "Укажите название системы, текст ошибки и время возникновения. Проверьте официальный адрес и язык ввода. Используйте штатное восстановление доступа. Не передавайте пароли или одноразовые коды. Конкретный канал и порядок предоставления прав необходимо подтвердить у ответственного подразделения."},
			{"employee_equipment", "IT", "Демо: неисправность рабочего оборудования", "принтер, компьютер, проектор, оборудование", "Укажите корпус, кабинет, инвентарный номер при наличии, признаки неисправности и влияние на работу. Не вскрывайте оборудование. При признаках опасности прекратите использование и сообщите ответственному по утверждённому порядку. Срок устранения этим шаблоном не устанавливается."},
			{"employee_hr", "HR", "Демо: кадровое обращение сотрудника", "кадровая справка, отпуск, кадровый документ", "Укажите вид кадрового документа или вопроса, назначение и желаемую дату. Документы с персональными данными передавайте через утверждённый защищённый канал. Порядок, форма и срок выдачи требуют проверки Управлением кадрового обеспечения."},
			{"employee_trip", "HR", "Демо: подготовка служебной командировки", "командировка, служебная поездка, согласование поездки", "Подготовьте цель, место, даты поездки, основание и предполагаемый источник финансирования без конфиденциальных сведений. Передайте запрос ответственному по действующему внутреннему порядку. Цепочку согласования, формы, суммы и сроки следует подтвердить по актуальному локальному акту. Этот шаблон не утверждает право на выплату или размер возмещения."},
			{"employee_advance", "Accounting", "Демо: проверка авансового отчёта", "авансовый отчет, расходы командировка, подтверждающие документы", "Укажите основание расходов и перечень имеющихся подтверждающих документов. Передайте материалы через утверждённый организацией канал. Не размещайте банковские реквизиты и копии персональных документов в открытой переписке. Действующие формы, сроки и состав документов необходимо подтвердить в бухгалтерии."},
			{"employee_records", "Records", "Демо: документооборот и регистрация", "документооборот, служебная записка, регистрация документа", "Укажите тип документа, назначение, инициатора и известный регистрационный номер без персональных данных. Используйте утверждённую систему документооборота. Маршрут подписания, список согласующих и срок регистрации этим шаблоном не устанавливаются."},
			{"employee_facilities", "Facilities", "Демо: административно-хозяйственное обращение", "кабинет, помещение, мебель, освещение", "Укажите корпус, кабинет, характер проблемы и возможность безопасно продолжать работу. При угрозе безопасности действуйте по утверждённому плану реагирования. Состав ответственных и срок исполнения необходимо подтвердить у организации."},
			{"employee_approval", "Approvals", "Демо: межподразделенческое согласование", "согласование, несколько подразделений, маршрут", "Укажите предмет согласования, известные участвующие подразделения и перечень приложений без конфиденциальных данных. Маршрут и полномочия согласующих должны быть заданы администратором по действующим правилам. Демонстрационная очередь не выполняет официальное согласование и не заменяет документооборот."},
			{"student_request", "Academic", "Демо: обращение обучающегося", "справка об обучении, студент, учебный вопрос", "Укажите вид учебного вопроса, требуемый документ и желаемую дату. Порядок обращения и срок исполнения уточните через официальный сервис университета. Этот шаблон поддерживает обучающихся наряду с внутренними процессами сотрудников."},
		}
	case "blank":
		t = OrganizationTemplate{Type: kind, Name: "Организация с нуля", Heading: "Служба поддержки", Builder: DefaultBuilderConfig(), Documents: []StarterDocument{}, Examples: []string{}}
		t.Builder.Departments = []Department{}
	case "it_company", "manufacturing", "retail", "medical", "logistics":
		t, _ = Organization("other")
		t.Type = kind
		t.Demonstration = true
		t.Notice = "Редактируемый стартовый шаблон. Не является отраслевым регламентом; рабочие маршруты и сроки утверждает организация."
		switch kind {
		case "it_company":
			t.Name = "IT-компания"
			t.Builder.Departments = []Department{{"IT", "Рабочие системы и доступ"}, {"Development", "Разработка и инфраструктура"}, {"HR", "Кадровые вопросы"}, {"Finance", "Финансовые вопросы"}}
			t.Examples = []string{"Не получается войти в рабочую систему.", "Нужен доступ к репозиторию проекта.", "Нужно оформить кадровый документ."}
		case "manufacturing":
			t.Name = "Производственное предприятие"
			t.Builder.Departments = []Department{{"Production", "Производственные обращения"}, {"Maintenance", "Обслуживание оборудования"}, {"IT", "Информационные системы"}, {"HR", "Кадровые вопросы"}}
			t.Examples = []string{"Оборудование выдаёт ошибку перед сменой.", "Не работает учётная система.", "Нужно согласовать обслуживание оборудования."}
		case "retail":
			t.Name = "Розничная торговля"
			t.Builder.Departments = []Department{{"IT", "Кассы и учётные системы"}, {"Supply", "Поставки"}, {"Facilities", "Эксплуатация торговых точек"}, {"HR", "Персонал"}}
			t.Examples = []string{"Не работает кассовая система.", "В поставке обнаружено расхождение.", "Не работает оборудование торгового зала."}
		case "medical":
			t.Name = "Медицинская организация"
			t.Builder.Departments = []Department{{"IT", "Информационные системы"}, {"Equipment", "Обслуживание оборудования"}, {"HR", "Персонал"}, {"Facilities", "Эксплуатация помещений"}}
			t.Examples = []string{"Не работает рабочая информационная система.", "Нужно передать оборудование на обслуживание.", "Нужно оформить кадровый документ."}
			t.Notice += " Только административные обращения; не содержит медицинских рекомендаций. Данные пациентов в обращение не включаются."
		case "logistics":
			t.Name = "Логистическая компания"
			t.Builder.Departments = []Department{{"Operations", "Операционные обращения"}, {"Warehouse", "Склад"}, {"IT", "Учётные системы"}, {"HR", "Персонал"}}
			t.Examples = []string{"Не работает складская учётная система.", "Нужно уточнить маршрут внутреннего документа.", "Оборудование склада выдаёт ошибку."}
		}
		t.Heading = "Внутренняя поддержка: " + t.Name
	default:
		return OrganizationTemplate{}, false
	}
	if kind != "financial_university" && kind != "blank" {
		known := map[string]bool{}
		for _, dept := range t.Builder.Departments {
			known[dept.Name] = true
		}
		for i := range t.Documents {
			if !known[t.Documents[i].Department] {
				replacement := "IT"
				for _, candidate := range []string{"Maintenance", "Equipment", "Warehouse", "Facilities"} {
					if known[candidate] {
						replacement = candidate
						break
					}
				}
				t.Documents[i].Department = replacement
			}
		}
	}

	t.Builder.StartTemplate = "Здравствуйте! Это служба поддержки: " + t.Name + ". Опишите ваш вопрос без паролей и конфиденциальных данных."
	return t, true
}
